INSERT INTO public.crops (id, name, default_yield_per_acre, yield_unit, active, color, bin_policy, test_weight_lb_per_bu, cheatsheet_md, crop_coefficient_id, min_return_years, rotation_notes, category, notes_planting, notes_growing, notes_harvest, notes_storage, needs_bins, counts_for_seeding, counts_for_harvest, progress_note, moisture_chart_key, moisture_dry_max, moisture_tough_max, moisture_damp_max, moisture_moist_max, moisture_note, moisture_dry_min, moisture_tough_advice, margin_per_acre, margin_source, renter_only, irrigation_need_in, max_in_a_row, stand_min_years, stand_max_years, own_use, feed_dm_pct, sister_value_per_acre, sister_value_note, land_rent_only, irrigation_need_basis, fixed_costs_apply, herbicide_trait, average_of, afsc_insured, yield_low_per_acre, yield_high_per_acre, days_to_maturity, goal_yield_per_acre, on_combines, weighed, farm_id, est_cleanout_pct) VALUES ('379c70a2-d783-48af-98f2-ace8415bb8da', 'Potato (kind not chosen)', NULL, 'cwt', true, '#8b5e3c', 'mixable', NULL, NULL, 'bf1ce9ec-f4b9-4d3c-bced-b423c4f588fb', 3, 'Minimum 3-4 yr break required. Verticillium, Rhizoctonia & PCN persist in soil. Canola shares Sclerotinia. Carrots host some same soil pathogens. Avoid any Solanaceae re-entry.', 'commercial', NULL, NULL, NULL, NULL, true, false, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, 16, 1, NULL, NULL, false, NULL, NULL, NULL, false, 'Evan Moore, 6 Oct 2026: about 16 in, the beginning of May to about the end of August', true, NULL, NULL, true, NULL, NULL, NULL, NULL, true, false, NULL, NULL);
