INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('fe8e5027-3d9a-43b3-9c0e-3031a5175c0d', '4695277f-d989-43f4-bcea-d08627951d3e', '46607ec6-e7c0-4699-821f-26fdb06870be', '2026-11-12 06:54:56.593193+00', 'possible', 'Works if the corn herbicides allow it (check the label carryover); heavy residue — seed shallow into a firm bed.', 'suggested');
